/*
 * A153351  Numbers k such that 7*k+2 is not prime.
 * https://oeis.org/A153351
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = the nth integer k such that 7*k+2 is not a prime number.
 *            The sequence is generated by searching k in ascending order and
 *            testing 7*k+2 with the provided primality test
 * Range:     u8 n <= 212, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   is_prime
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>
#include "../utils/is_prime.h"

static seq_t *cache = NULL;          /* cache of found terms */
static size_t cap   = 0;             /* allocated capacity (in elements) */
static size_t len   = 0;             /* number of cached terms */
static idx_t   last_k = 0;           /* last k value examined */

/* Helper to grow the cache array */
static void grow_cache(void) {
    size_t new_cap = cap ? cap * 2 : 1024;
    seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
    if (!tmp) exit(1);               /* impossible in this context */
    cache = tmp;
    cap = new_cap;
}

/* Return the nth term of the sequence (1-indexed). */
seq_t a(idx_t n)
{
    if (n == 0) return 0;            /* undefined, but safe */

    /* Ensure we have at least n terms cached. */
    while (len < (size_t)n) {
        if (len == cap) grow_cache();

        last_k++;
        /* 7*last_k+2 fits within idx_t for the expected ranges. */
        idx_t m = 7 * last_k + 2;
        /* is_prime returns true if m is prime; we want the complement. */
        if (!is_prime(m)) {
            cache[len++] = (seq_t)last_k;
        }
    }

    return cache[n - 1];
}
